export function getWheelPageContent(locale, slug) {
  if (WHEEL_PAGE_CONTENT[slug] && WHEEL_PAGE_CONTENT[slug][locale]) {
    return WHEEL_PAGE_CONTENT[slug][locale];
  }
  if (WHEEL_PAGE_CONTENT[slug] && WHEEL_PAGE_CONTENT[slug]['en']) {
    return WHEEL_PAGE_CONTENT[slug]['en'];
  }
  return null;
}
